<script setup lang="ts">type Series={id:string;name:string;slug:string;description:string|null;coverUrl:string|null;seoTitle:string|null;seoDescription:string|null;posts:Array<{postId:string;post:{id:string;title:string;status:string}} >};type Post={id:string;title:string;status:string};definePageMeta({layout:'admin',middleware:'admin'});const {data,refresh}=await useFetch<Series[]>('/api/admin/series');const {data:posts}=await useFetch<Post[]>('/api/admin/posts');const csrf=useCsrf();const open=ref(false);const editing=ref<Series|null>(null);const m=reactive({name:'',slug:'',description:'',coverUrl:'',seoTitle:'',seoDescription:'',postIds:[] as string[]});function start(s?:Series){editing.value=s||null;Object.assign(m,{name:s?.name||'',slug:s?.slug||'',description:s?.description||'',coverUrl:s?.coverUrl||'',seoTitle:s?.seoTitle||'',seoDescription:s?.seoDescription||'',postIds:s?.posts.map(p=>p.postId)||[]});open.value=true}async function save(){await $fetch(editing.value?`/api/admin/series/${editing.value.id}`:'/api/admin/series',{method:editing.value?'PUT':'POST',headers:csrf.value,body:m});open.value=false;await refresh()}async function remove(s:Series){await $fetch(`/api/admin/series/${s.id}`,{method:'DELETE',headers:csrf.value});await refresh()}function move(i:number,d:number){const j=i+d;if(j<0||j>=m.postIds.length)return;[m.postIds[i],m.postIds[j]]=[m.postIds[j]!,m.postIds[i]!]}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">系列</h1><button class="rounded-full px-5 py-2 text-white" style="background:var(--accent)" @click="start()">新建系列</button></div><section v-for="s in data||[]" :key="s.id" class="mt-5 rounded-xl border p-5" style="border-color:var(--border)"><div class="flex justify-between"><div><h2 class="text-xl font-semibold">{{s.name}}</h2><p class="text-sm">{{s.slug}} · {{s.posts.length}} 篇</p></div><div class="flex gap-3"><button @click="start(s)">编辑与排序</button><button @click="remove(s)">删除</button></div></div><ol class="mt-3 list-inside list-decimal"> <li v-for="p in s.posts" :key="p.postId">{{p.post.title}}</li></ol><NuxtLink :to="`/series/${s.slug}`" class="mt-3 inline-block underline">查看前台系列</NuxtLink></section><div v-if="open" class="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" @click.self="open=false"><form class="max-h-[90vh] w-full max-w-2xl overflow-auto rounded-2xl p-6" style="background:var(--surface)" @submit.prevent="save"><h2 class="text-xl font-semibold">{{editing?'编辑':'新建'}}系列</h2><div class="mt-4 grid gap-3"><input v-model="m.name" required placeholder="名称" class="rounded border bg-transparent p-2"><input v-model="m.slug" required placeholder="slug" class="rounded border bg-transparent p-2"><textarea v-model="m.description" placeholder="描述" class="rounded border bg-transparent p-2"/><input v-model="m.coverUrl" placeholder="封面 URL" class="rounded border bg-transparent p-2"><input v-model="m.seoTitle" placeholder="SEO 标题" class="rounded border bg-transparent p-2"><input v-model="m.seoDescription" placeholder="SEO 描述" class="rounded border bg-transparent p-2"><h3 class="mt-2 font-semibold">选择文章与排序</h3><label v-for="p in posts||[]" :key="p.id" class="flex items-center gap-2"><input v-model="m.postIds" type="checkbox" :value="p.id">{{p.title}} <small>{{p.status}}</small></label><div class="border-t pt-3"><div v-for="id,i in m.postIds" :key="id" class="flex justify-between py-1"><span>{{posts?.find(p=>p.id===id)?.title}}</span><span><button type="button" @click="move(i,-1)">↑</button><button type="button" @click="move(i,1)">↓</button></span></div></div></div><div class="mt-5 flex justify-end gap-3"><button type="button" @click="open=false">取消</button><button class="rounded-lg px-4 py-2 text-white" style="background:var(--accent)">保存</button></div></form></div></div></template>
